    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    // --- Quote edge cases ---

    #[test]
    fn empty_double_quoted_value() {
        let vars = EnvFileParser::parse(r#"KEY="""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn empty_single_quoted_value() {
        let vars = EnvFileParser::parse("KEY=''").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn mismatched_quotes_double_then_single() {
        // Starts with " but ends with ' — not a matched pair, kept as-is
        let vars = EnvFileParser::parse(r#"KEY="value'"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#""value'"#.to_string()));
    }

    #[test]
    fn mismatched_quotes_single_then_double() {
        let vars = EnvFileParser::parse(r#"KEY='value""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"'value""#.to_string()));
    }

    #[test]
    fn value_with_only_opening_double_quote() {
        let vars = EnvFileParser::parse(r#"KEY="no closing"#).unwrap();
        // Single quote char — not a pair, returned as-is
        assert_eq!(vars.get("KEY"), Some(&r#""no closing"#.to_string()));
    }

    #[test]
    fn value_with_only_opening_single_quote() {
        let vars = EnvFileParser::parse("KEY='no closing").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'no closing".to_string()));
    }

    #[test]
    fn single_double_quote_char_as_value() {
        let vars = EnvFileParser::parse(r#"KEY=""#).unwrap();
        // A lone `"` — length 1, starts_with and ends_with both true
        // but len < 2 guard keeps it as-is
        assert_eq!(vars.get("KEY"), Some(&r#"""#.to_string()));
    }

    #[test]
    fn single_single_quote_char_as_value() {
        let vars = EnvFileParser::parse("KEY='").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn quoted_value_preserves_inner_whitespace() {
        let vars = EnvFileParser::parse(r#"KEY="  leading and trailing  ""#).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"  leading and trailing  ".to_string())
        );
    }

    #[test]
    fn quotes_embedded_inside_value_not_stripped() {
        // Quotes in the middle are not surrounding quotes
        let vars = EnvFileParser::parse(r#"KEY=say "hello" world"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say "hello" world"#.to_string()));
    }

    #[test]
    fn escaped_double_quotes_inside_double_quotes() {
        // The parser does NOT handle escape sequences — backslashes are literal
        let vars = EnvFileParser::parse(r#"KEY="value with \"escaped\" quotes""#).unwrap();
        // The outer quotes are stripped, inner backslashes and quotes remain
        assert_eq!(
            vars.get("KEY"),
            Some(&r#"value with \"escaped\" quotes"#.to_string())
        );
    }

    #[test]
    fn escaped_single_quotes_inside_single_quotes() {
        let vars = EnvFileParser::parse(r"KEY='it\'s a test'").unwrap();
        // Outer quotes stripped, backslash kept literally
        assert_eq!(vars.get("KEY"), Some(&r"it\'s a test".to_string()));
    }

    #[test]
    fn backslash_n_in_double_quotes_is_literal() {
        let vars = EnvFileParser::parse(r#"KEY="line1\nline2""#).unwrap();
        // No escape interpretation — literal \n
        assert_eq!(vars.get("KEY"), Some(&r"line1\nline2".to_string()));
    }

    // --- Inline comment edge cases ---

    #[test]
    fn inline_comment_not_stripped_from_unquoted_value() {
        // The parser does NOT strip inline comments
        let vars = EnvFileParser::parse("KEY=value # comment").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value # comment".to_string()));
    }

    #[test]
    fn hash_inside_quoted_value_preserved() {
        let vars = EnvFileParser::parse(r#"KEY="value#with#hash""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value#with#hash".to_string()));
    }

    #[test]
    fn comment_line_with_leading_whitespace() {
        let vars = EnvFileParser::parse("   # indented comment\nKEY=val").unwrap();
        assert_eq!(vars.len(), 1);
        assert_eq!(vars.get("KEY"), Some(&"val".to_string()));
    }

    // --- Key edge cases ---

    #[test]
    fn key_with_no_value_just_equals() {
        // `=value` produces an empty key
        let vars = EnvFileParser::parse("=value").unwrap();
        assert_eq!(vars.get(""), Some(&"value".to_string()));
    }

    #[test]
    fn bare_equals_sign() {
        let vars = EnvFileParser::parse("=").unwrap();
        assert_eq!(vars.get(""), Some(&"".to_string()));
    }

    #[test]
    fn duplicate_keys_last_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn key_with_dots() {
        let vars = EnvFileParser::parse("my.dotted.key=value").unwrap();
        assert_eq!(vars.get("my.dotted.key"), Some(&"value".to_string()));
    }

    #[test]
    fn key_with_dashes_and_underscores() {
        let vars = EnvFileParser::parse("MY-KEY_NAME=value").unwrap();
        assert_eq!(vars.get("MY-KEY_NAME"), Some(&"value".to_string()));
    }

    // --- Whitespace edge cases ---

    #[test]
    fn tabs_around_equals() {
        let vars = EnvFileParser::parse("KEY\t=\tvalue").unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn leading_and_trailing_whitespace_on_line() {
        let vars = EnvFileParser::parse("   KEY=value   ").unwrap();
        // Line is trimmed, so KEY=value is parsed; value keeps trailing space
        // after equals: "value   " gets trimmed by value.trim()
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn value_whitespace_preserved_inside_quotes() {
        let vars = EnvFileParser::parse(r#"KEY="  hello  ""#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"  hello  ".to_string()));
    }

    #[test]
    fn only_whitespace_lines_skipped() {
        let content = "  \n\t\nKEY=val\n  \t  ";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.len(), 1);
    }

    // --- Special value content ---

    #[test]
    fn value_with_multiple_equals_signs() {
        let vars = EnvFileParser::parse("BASE64=dGVzdA==").unwrap();
        assert_eq!(vars.get("BASE64"), Some(&"dGVzdA==".to_string()));
    }

    #[test]
    fn quoted_value_with_equals_signs() {
        let vars = EnvFileParser::parse(r#"URL="https://x.com?a=1&b=2""#).unwrap();
        assert_eq!(
            vars.get("URL"),
            Some(&"https://x.com?a=1&b=2".to_string())
        );
    }

    #[test]
    fn value_with_special_chars() {
        let vars = EnvFileParser::parse("SPECIAL=!@$%^&*()").unwrap();
        assert_eq!(vars.get("SPECIAL"), Some(&"!@$%^&*()".to_string()));
    }

    #[test]
    fn value_with_unicode() {
        let vars = EnvFileParser::parse("GREETING=こんにちは").unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"こんにちは".to_string()));
    }

    // --- File I/O ---

    #[test]
    fn load_reads_file_from_disk() {
        let dir = tempfile::TempDir::new().unwrap();
        let env_path = dir.path().join(".env");
        std::fs::write(&env_path, "FROM_FILE=yes\n").unwrap();

        let vars = EnvFileParser::load(&env_path).unwrap();
        assert_eq!(vars.get("FROM_FILE"), Some(&"yes".to_string()));
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = tempfile::TempDir::new().unwrap();
        let env_path = dir.path().join(".env");
        std::fs::write(&env_path, "OPT=yes\n").unwrap();

        let vars = EnvFileParser::load_optional(&env_path).unwrap();
        assert_eq!(vars.get("OPT"), Some(&"yes".to_string()));
    }

    // --- Empty / edge-case inputs ---

    #[test]
    fn empty_string_returns_empty_map() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn only_comments_returns_empty_map() {
        let vars = EnvFileParser::parse("# comment\n# another").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn windows_line_endings() {
        let vars = EnvFileParser::parse("KEY1=val1\r\nKEY2=val2\r\n").unwrap();
        // \r is not stripped by lines() on all platforms, value may include \r
        // The important thing is both keys are parsed
        assert_eq!(vars.len(), 2);
        assert!(vars.contains_key("KEY1"));
        assert!(vars.contains_key("KEY2"));
    }

    #[test]
    fn export_prefix_becomes_part_of_key() {
        // The parser does NOT handle `export` prefix — it becomes part of the key
        let vars = EnvFileParser::parse("export KEY=value").unwrap();
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }
}

