        // Quotes in the middle are not surrounding quotes
        let vars = EnvFileParser::parse(r#"KEY=say "hello" world"#).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say "hello" world"#.to_string()));
    }

    #[test]
    fn escaped_double_quotes_inside_double_quotes() {
        // The parser does NOT handle escape sequences — backslashes are literal
        let vars = EnvFileParser::parse(r#"KEY="value with \"escaped\" quotes""#).unwrap();
        // The outer quotes are stripped, inner backslashes and quotes remain
        assert_eq!(
            vars.get("KEY"),
            Some(&r#"value with \"escaped\" quotes"#.to_string())
        );
    }

    #[test]
    fn escaped_single_quotes_inside_single_quotes() {
